import itertools

def count_words_with_g(words):
    return sum(1 for word in words if 'G' in word)

def count_words_without_g(words):
    return sum(1 for word in words if 'G' not in word)

def count_words_with_g_or_without_g(words):
    return count_words_with_g(words) + count_words_without_g(words)

def count_words_with_g_or_without_g_in_all_possible_groupings():
    total_words = 0
    for grouping in itertools.combinations(range(12), 6):
        words = [''.join(pair) for pair in zip(*sorted(zip(grouping, grouping[::-1]))))
        total_words += count_words_with_g_or_without_g(words)
    return total_words

total_words_with_g_or_without_g_in_all_possible_groupings = count_words_with_g_or_without_g_in_all_possible_groupings()
total_words_without_g_in_all_possible_groupings = count_words_without_g_in_all_possible_groupings()

probability_with_g = count_words_with_g_or_without_g_in_all_possible_groupings / total_words_with_g_or_without_g_in_all_possible_groupings
probability_without_g = total_words_without_g_in_all_possible_groupings / total_words_with_g_or_without_g_in_all_possible_groupings

print(f"Probability that the last word contains G: {probability_with_g}")
print(f"Probability that the last word does not contain G: {probability_without_g}")

